// Writes src/generated/tokens.css and src/generated/tokens.ts from tokens/*.tokens.json.
// `node scripts/build-tokens.mjs --check` writes nothing and fails when the generated files are stale.
import { readFileSync, writeFileSync } from "node:fs";
import path from "node:path";
import { fileURLToPath } from "node:url";
import { MODES, UI_ROOT, cssDeclarations, flatten, isEmitted, isShared, loadMode, readTokenFile } from "./tokens-lib.mjs";

const HEADER = "Generated by packages/ui/scripts/build-tokens.mjs from packages/ui/tokens/. Don't edit: change the tokens and run `npm run ui:tokens`.";

function block(selector, declarations, extra = []) {
  const lines = [...extra, ...declarations.map(([name, value]) => `${name}: ${value};`)];
  return `${selector} {\n${lines.map((l) => `  ${l}`).join("\n")}\n}`;
}

function declarationsFor(mode, keep) {
  const tokens = loadMode(mode);
  const out = [];
  for (const [p, t] of tokens) if (isEmitted(p) && keep(p)) out.push(...cssDeclarations(p, t, tokens));
  return out;
}

/** The roles a contrast file overrides, resolved against its whole mode. */
function overrides(mode) {
  const file = MODES[mode].at(-1);
  const changed = new Set(flatten(readTokenFile(file)).keys());
  return declarationsFor(mode, (p) => changed.has(p));
}

export function buildCss() {
  const shared = declarationsFor("light", isShared);
  const light = declarationsFor("light", (p) => !isShared(p));
  const dark = declarationsFor("dark", (p) => !isShared(p));
  const moreLight = overrides("contrast-light");
  const moreDark = overrides("contrast-dark");
  const indent = (css) => css.split("\n").map((l) => (l ? `  ${l}` : l)).join("\n");
  return [
    `/* ${HEADER}\n   Light is the default; dark follows the system, and data-appearance="light|dark" pins a subtree\n   (the gallery and the screenshot tests use it). Increase Contrast follows the system, and\n   data-contrast="more" pins it. */`,
    block(":root", shared),
    block(':root, [data-appearance="light"]', light, ["color-scheme: light;"]),
    block('[data-appearance="dark"]', dark, ["color-scheme: dark;"]),
    `@media (prefers-color-scheme: dark) {\n${indent(block(':root:not([data-appearance="light"])', dark, ["color-scheme: dark;"]))}\n}`,
    `@media (prefers-contrast: more) {\n${indent(block(':root, [data-appearance="light"]', moreLight))}\n${indent(block('[data-appearance="dark"]', moreDark))}\n}`,
    `@media (prefers-contrast: more) and (prefers-color-scheme: dark) {\n${indent(block(':root:not([data-appearance="light"])', moreDark))}\n}`,
    block('[data-contrast="more"]', moreLight),
    block('[data-contrast="more"][data-appearance="dark"]', moreDark),
    "",
  ].join("\n\n");
}

export function buildTs() {
  const tokens = loadMode("light");
  const keys = (group) => [...tokens.keys()].filter((p) => p.startsWith(`${group}.`)).map((p) => p.slice(group.length + 1));
  const names = [];
  for (const [p, t] of tokens) if (isEmitted(p)) for (const [n] of cssDeclarations(p, t, tokens)) names.push(n);
  const list = (xs, quote = true) => xs.map((x) => (quote ? JSON.stringify(x) : x)).join(", ");
  return `// ${HEADER}

/** The spacing steps, in px. Gaps, paddings and margins use only these. */
export const SPACE = [${list(keys("space").map(Number), false)}] as const;
export type Space = (typeof SPACE)[number];

/** The library's shelves, in the order the menu lists them. */
export const SHELVES = [${list(keys("shelf"))}] as const;
export type Shelf = (typeof SHELVES)[number];

export const RADII = [${list(keys("radius"))}] as const;
export type Radius = (typeof RADII)[number];

export const LAYERS = [${list(keys("layer"))}] as const;
export type Layer = (typeof LAYERS)[number];

export const TEXT_STYLES = [${list(keys("text"))}] as const;
export type TextStyle = (typeof TEXT_STYLES)[number];

/** Every CSS custom property the token build writes. */
export const TOKEN_NAMES = [
${names.map((n) => `  ${JSON.stringify(n)},`).join("\n")}
] as const;
export type TokenName = (typeof TOKEN_NAMES)[number];
`;
}

const outputs = [
  [path.join(UI_ROOT, "src", "generated", "tokens.css"), buildCss],
  [path.join(UI_ROOT, "src", "generated", "tokens.ts"), buildTs],
];

if (fileURLToPath(import.meta.url) === path.resolve(process.argv[1] ?? "")) {
  const check = process.argv.includes("--check");
  const stale = [];
  for (const [file, build] of outputs) {
    const next = build();
    let current = "";
    try { current = readFileSync(file, "utf8"); } catch {}
    if (current === next) continue;
    if (check) stale.push(path.relative(process.cwd(), file));
    else writeFileSync(file, next);
  }
  if (stale.length) {
    console.error(`Generated token files are stale: ${stale.join(", ")}. Run \`npm run ui:tokens\`.`);
    process.exit(1);
  }
  console.log(check ? "Token files are up to date." : "Wrote src/generated/tokens.css and tokens.ts.");
}
